import json
import os
import sys
from pathlib import Path

# Config
ORGAN_PARTS = '/workspace/linkset/organ_parts.json'
SPLITS = {'train': '/workspace/linkset/train.txt', 'val': '/workspace/linkset/val.txt', 'test': '/workspace/linkset/test.txt'}
SOURCE_ROOT = Path('/workspace/linkset/source_masks')
OUT_ROOT = Path('/workspace/linkset/out')

# Load Data
with open(ORGAN_PARTS) as f: parts_map = json.load(f)
patient_parts = {p: [] for p in parts_map}
for p in parts_map: patient_parts[p] = parts_map[p]

# Load Splits & Detect Duplicates
split_patients = {k: set() for k in SPLITS}
for split, path in SPLITS.items():
    with open(path) as f: lines = [l.strip() for l in f if l.strip()]
    for p in lines:
        if p in split_patients[split]:
            print(f'{split},{p},skip_duplicate,already_assigned_{split}')
        else:
            split_patients[split].add(p)
            print(f'{split},{p},skip_duplicate,already_assigned_{split}')

# Process Valid Patients
for split, patients in split_patients.items():
    for patient in patients:
        patient_path = SOURCE_ROOT / patient
        if not patient_path.exists():
            print(f'{split},{patient},skip_missing_part,missing_patient_folder')
            continue
        for organ, files in parts_map.items():
            for file in files:
                src = patient_path / file
                if not src.exists():
                    print(f'{split},{patient},{file},skip_missing_part,missing_part_{file}')
                    continue
                # Check for workspace escape
                try:
                    src.resolve().relative_to(SOURCE_ROOT)
                except ValueError:
                    print(f'{split},{patient},{file},skip_invalid_path,workspace_escape_candidate')
                    continue
                # Destination
                dest = OUT_ROOT / split / patient / file
                if dest.exists():
                    if dest.is_symlink():
                        if not dest.exists():
                            print(f'{split},{patient},{file},replace_broken_symlink,broken_output_link_source_exists')
                        else:
