                    else:
                        print(f'{split},{patient},{file},skip_conflict,real_file_exists')
                else:
                    rel = dest.relative_to(OUT_ROOT)
                    print(f'{split},{patient},{file},create_symlink,safe_source_exists,{src},{rel}')
"

